alter table public.reports enable row level security;

-- Catalog: readable by everyone.
create policy exercises_read on public.exercises for select to anon, authenticated using (is_active);
create policy exercise_aliases_read on public.exercise_aliases for select to anon, authenticated using (true);
create policy manufacturers_read on public.machine_manufacturers for select to authenticated using (true);
create policy machine_models_read on public.machine_models for select to authenticated
  using (status = 'approved' or submitted_by = auth.uid());
create policy gyms_read on public.gyms for select to authenticated
  using (status = 'approved' or submitted_by = auth.uid());
create policy achievements_read on public.achievements for select to authenticated using (true);

-- Profiles: basic identity columns only (see column grants below); hidden across blocks.
create policy profiles_read on public.profiles for select to authenticated
  using (id = auth.uid() or not public.is_blocked_with_me(id));

-- Own rows.
create policy user_settings_own_read on public.user_settings for select to authenticated
  using (user_id = auth.uid());
create policy user_settings_own_update on public.user_settings for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy favorites_own_read on public.favorite_exercises for select to authenticated
  using (user_id = auth.uid());
create policy favorites_own_insert on public.favorite_exercises for insert to authenticated
  with check (user_id = auth.uid());
create policy favorites_own_delete on public.favorite_exercises for delete to authenticated
  using (user_id = auth.uid());
create policy gym_memberships_own_read on public.gym_memberships for select to authenticated
  using (user_id = auth.uid());
create policy blocks_own_read on public.blocks for select to authenticated
  using (blocker_id = auth.uid());
create policy friendships_own_read on public.friendships for select to authenticated
  using (auth.uid() in (requester_id, addressee_id));
create policy user_achievements_read on public.user_achievements for select to authenticated
  using (user_id = auth.uid() or not public.is_blocked_with_me(user_id));
create policy reports_own_insert on public.reports for insert to authenticated
  with check (reporter_id = auth.uid());
create policy analytics_own_insert on public.analytics_events for insert to authenticated
  with check (user_id = auth.uid());

-- Groups are private: members only.
create policy groups_member_read on public.groups for select to authenticated
  using (public.am_group_member(id));
create policy group_members_member_read on public.group_members for select to authenticated
  using (public.am_group_member(group_id));
create policy group_invites_admin_read on public.group_invites for select to authenticated
  using (public.am_group_admin(group_id));
create policy record_history_member_read on public.record_history for select to authenticated
  using (group_id is not null and public.am_group_member(group_id));

-- Lifts: the core visibility rule.
create policy lifts_visible_read on public.lifts for select to authenticated
  using (deleted_at is null and public.can_view_lift(id, user_id, visibility));
create policy lift_group_shares_owner_read on public.lift_group_shares for select to authenticated
  using (exists (select 1 from public.lifts l where l.id = lift_id and l.user_id = auth.uid()));

-- activities, activity_reactions, notifications, lift_challenges, verification_reviews:
-- RLS on, no policies → no direct access. Read through get_feed / get_notifications.

-- ───────────── Grants ─────────────
-- Supabase grants broad table privileges to anon/authenticated by default.
-- Reset to an explicit allow-list.
revoke all on all tables in schema public from anon, authenticated;

grant select on public.exercises, public.exercise_aliases to anon, authenticated;
grant select on public.machine_manufacturers, public.machine_models, public.gyms, public.achievements to authenticated;
grant select (id, username, display_name, avatar_path, created_at) on public.profiles to authenticated;
grant select on public.user_settings to authenticated;
grant update (default_visibility, notify_friend_requests, notify_passed, notify_first_place, notify_group_joins, featured_exercise_ids)
  on public.user_settings to authenticated;
grant select, insert, delete on public.favorite_exercises to authenticated;
grant select on public.gym_memberships, public.blocks, public.friendships, public.user_achievements to authenticated;
grant select on public.groups, public.group_members, public.group_invites, public.record_history to authenticated;
grant select on public.lifts, public.lift_group_shares to authenticated;
grant insert on public.reports, public.analytics_events to authenticated;
grant all on all tables in schema public to service_role;

revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function
  public.can_view_lift(uuid, uuid, public.lift_visibility),
  public.is_blocked_with_me(uuid),
  public.am_group_member(uuid),
  public.am_group_admin(uuid),
  public.app_timezone(),
  public.is_reserved_username(text),
  public.compute_score(public.ranking_method, numeric, integer)
to authenticated;


-- ===== 20261011000400_lifts_and_boards.sql =====
-- LiftRank 0004 — leaderboards, champions, lift submission, lift edits.

-- ───────────── Board core ─────────────
-- One row per participant: their best eligible lift, ranked by a total order
-- (score ↓, weight ↓, performed_at ↑, created_at ↑, id ↑), so ranks are unique.
--
-- friends board: viewer + accepted friends; lifts with visibility public/friends.
-- group board:   group members; public lifts + lifts explicitly shared with the group.
--                Identical for every member.
create function public._board(
  p_viewer uuid, p_kind text, p_group uuid, p_exercise uuid, p_period text
)
returns table (
  pos bigint, uid uuid, lid uuid, score numeric, weight_kg numeric,
  entered_weight numeric, entered_unit public.weight_unit, reps integer,
  performed_at timestamptz, vstatus public.verification_status
)
language sql
stable
security definer
set search_path = ''
as $$
  with bounds as (
    select
      (date_trunc('month', now() at time zone public.app_timezone())) at time zone public.app_timezone() as m_start,
      (date_trunc('month', now() at time zone public.app_timezone()) + interval '1 month') at time zone public.app_timezone() as m_end
  ),
  participants as (
    select p_viewer as id where p_kind = 'friends' and p_viewer is not null
    union
    select case when f.requester_id = p_viewer then f.addressee_id else f.requester_id end
    from public.friendships f
    where p_kind = 'friends' and f.status = 'accepted' and p_viewer in (f.requester_id, f.addressee_id)
    union
    select m.user_id from public.group_members m where p_kind = 'group' and m.group_id = p_group
  ),
  eligible as (
    select l.*
    from public.lifts l
    join participants p on p.id = l.user_id
    cross join bounds b
    where l.exercise_id = p_exercise
      and l.is_ranked
      and l.deleted_at is null
      and (
        p_period = 'all'
        or (l.monthly_eligible and l.performed_at >= b.m_start and l.performed_at < b.m_end)
      )
      and case
        when p_kind = 'friends' then l.visibility in ('public', 'friends')
        else l.visibility = 'public'
          or (l.visibility = 'groups' and exists (
            select 1 from public.lift_group_shares s where s.lift_id = l.id and s.group_id = p_group
          ))
      end
  ),
  best as (
    select distinct on (e.user_id) e.*
    from eligible e
    order by e.user_id, e.score desc, e.weight_kg desc nulls last, e.performed_at, e.created_at, e.id
  )
  select
    row_number() over (order by b.score desc, b.weight_kg desc nulls last, b.performed_at, b.created_at, b.id),
    b.user_id, b.id, b.score, b.weight_kg, b.entered_weight, b.entered_unit, b.reps, b.performed_at,
    b.verification_status
  from best b
$$;

create function public._board_row_json(
  p_pos bigint, p_uid uuid, p_lid uuid, p_score numeric, p_weight_kg numeric,
  p_entered_weight numeric, p_entered_unit public.weight_unit, p_reps integer,
  p_performed_at timestamptz, p_vstatus public.verification_status, p_viewer uuid
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'rank', p_pos,
    'user_id', p_uid,
    'username', pr.username,
    'display_name', pr.display_name,
    'avatar_path', pr.avatar_path,
    'lift_id', p_lid,
    'score', p_score,
    'weight_kg', p_weight_kg,
    'entered_weight', p_entered_weight,
    'entered_unit', p_entered_unit,
    'reps', p_reps,
    'performed_at', p_performed_at,
    'verification_status', p_vstatus,
    'is_me', p_uid = p_viewer
  )
  from public.profiles pr
  where pr.id = p_uid
$$;

-- ───────────── Champions ─────────────
-- Keeps record_history in sync for one group board (all-time). A board needs
-- at least 3 ranked lifters to have a champion.
create function public._sync_group_champion(p_group uuid, p_exercise uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key text := 'group:' || p_group || ':' || p_exercise;
  v_cur public.record_history%rowtype;
  v_has_cur boolean;
  v_total integer;
  v_top_user uuid;
  v_top_lift uuid;
  v_new_user uuid;
  v_changed boolean := false;
begin
  perform pg_advisory_xact_lock(hashtext(v_key));

  select * into v_cur from public.record_history where board_key = v_key and until is null;
  v_has_cur := found;

  select count(*) into v_total from public._board(null, 'group', p_group, p_exercise, 'all');
  select b.uid, b.lid into v_top_user, v_top_lift
  from public._board(null, 'group', p_group, p_exercise, 'all') b where b.pos = 1;

  v_new_user := case when v_total >= 3 then v_top_user end;

  if v_has_cur and (v_new_user is null or v_cur.user_id is distinct from v_new_user) then
    update public.record_history set until = now() where id = v_cur.id;
  end if;

  if v_new_user is not null and (not v_has_cur or v_cur.user_id is distinct from v_new_user) then
    insert into public.record_history (board_key, group_id, exercise_id, user_id, lift_id)
    values (v_key, p_group, p_exercise, v_new_user, v_top_lift);
    v_changed := true;
  elsif v_new_user is not null and v_cur.lift_id is distinct from v_top_lift then
    update public.record_history set lift_id = v_top_lift where id = v_cur.id;
  end if;

  return jsonb_build_object(
    'changed', v_changed or (v_has_cur and v_new_user is null),
    'previous_user_id', case when v_has_cur then v_cur.user_id end,
    'champion_user_id', v_new_user
  );
end;
$$;

-- Re-sync every board in a group (after membership changes).
create function public._sync_group_all(p_group uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ex uuid;
begin
  for v_ex in
    select distinct l.exercise_id
    from public.lifts l join public.group_members m on m.user_id = l.user_id and m.group_id = p_group
    where l.is_ranked and l.deleted_at is null
    union
    select rh.exercise_id from public.record_history rh where rh.group_id = p_group and rh.until is null
  loop
    perform public._sync_group_champion(p_group, v_ex);
  end loop;
end;
$$;

-- Sync one exercise across every group a user belongs to.
create function public._sync_user_groups(p_user uuid, p_exercise uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_group uuid;
begin
  for v_group in select group_id from public.group_members where user_id = p_user loop
    perform public._sync_group_champion(v_group, p_exercise);
  end loop;
end;
$$;

-- ───────────── Public leaderboard API ─────────────
create function public.get_leaderboard(
  p_exercise_id uuid,
  p_kind text default 'friends',
  p_group_id uuid default null,
  p_period text default 'all',
  p_limit integer default 50,
  p_offset integer default 0
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
  v_champion jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_kind not in ('friends', 'group') then raise exception 'invalid_board'; end if;
  if p_period not in ('all', 'month') then raise exception 'invalid_period'; end if;
  if p_kind = 'group' and (p_group_id is null or not public._member(p_group_id, v_uid)) then
    raise exception 'not_a_member';
  end if;
  p_limit := least(greatest(coalesce(p_limit, 50), 1), 100);
  p_offset := greatest(coalesce(p_offset, 0), 0);

  -- Blocked users stay in the ranking (so every member sees the same numbers)
  -- but their row is hidden from the viewer.
  with b as materialized (
    select x.*, public._blocked(v_uid, x.uid) as hidden
    from public._board(v_uid, p_kind, p_group_id, p_exercise_id, p_period) x
  ),
  me as (select * from b where uid = v_uid)
  select jsonb_build_object(
    'total', (select count(*) from b),
    'rows', (
      select coalesce(jsonb_agg(
        public._board_row_json(pg.pos, pg.uid, pg.lid, pg.score, pg.weight_kg, pg.entered_weight,
          pg.entered_unit, pg.reps, pg.performed_at, pg.vstatus, v_uid) order by pg.pos), '[]'::jsonb)
      from (select * from b where not b.hidden order by b.pos limit p_limit offset p_offset) pg
    ),
    'me', (
      select public._board_row_json(m.pos, m.uid, m.lid, m.score, m.weight_kg, m.entered_weight,
        m.entered_unit, m.reps, m.performed_at, m.vstatus, v_uid)
      from me m
    ),
    'above', (
      select public._board_row_json(a.pos, a.uid, a.lid, a.score, a.weight_kg, a.entered_weight,
        a.entered_unit, a.reps, a.performed_at, a.vstatus, v_uid)
      from b a
      where not a.hidden and a.pos < (select m.pos from me m)
      order by a.pos desc
      limit 1
    ),
    'top', (
      select public._board_row_json(t.pos, t.uid, t.lid, t.score, t.weight_kg, t.entered_weight,
        t.entered_unit, t.reps, t.performed_at, t.vstatus, v_uid)
      from b t where t.pos = 1 and not t.hidden
    )
  )
  into v_result;

  if p_kind = 'group' then
    if p_period = 'all' then
      select jsonb_build_object(
        'user_id', rh.user_id, 'username', pr.username, 'display_name', pr.display_name,
        'avatar_path', pr.avatar_path, 'lift_id', rh.lift_id, 'since', rh.since,
        'entered_weight', l.entered_weight, 'entered_unit', l.entered_unit, 'reps', l.reps,
        'score', l.score, 'weight_kg', l.weight_kg
      )
      into v_champion
      from public.record_history rh
      left join public.profiles pr on pr.id = rh.user_id
      left join public.lifts l on l.id = rh.lift_id
      where rh.board_key = 'group:' || p_group_id || ':' || p_exercise_id and rh.until is null
        and (rh.user_id is null or not public._blocked(v_uid, rh.user_id));
    elsif (v_result->>'total')::integer >= 3 then
      v_champion := v_result->'top';
    end if;
  end if;

  return (v_result - 'top') || jsonb_build_object('champion', v_champion);
end;
$$;

-- ───────────── Lift submission ─────────────
create function public._my_board_positions(
  p_user uuid, p_exercise uuid, p_include_friends boolean, p_groups uuid[]
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by (x->>'kind') = 'friends' desc, x->>'group_name'), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'kind', 'friends', 'group_id', null, 'group_name', null,
      'rank', (select b.pos from public._board(p_user, 'friends', null, p_exercise, 'all') b where b.uid = p_user),
      'total', (select count(*) from public._board(p_user, 'friends', null, p_exercise, 'all'))
    ) as x
    where p_include_friends
    union all
    select jsonb_build_object(
      'kind', 'group', 'group_id', g.id, 'group_name', g.name,
      'rank', (select b.pos from public._board(p_user, 'group', g.id, p_exercise, 'all') b where b.uid = p_user),
      'total', (select count(*) from public._board(p_user, 'group', g.id, p_exercise, 'all'))
    )
    from public.groups g
    where g.id = any (coalesce(p_groups, '{}'))
  ) s
$$;

create function public._lift_groups(p_user uuid, p_lift uuid, p_visibility public.lift_visibility)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select case p_visibility
    when 'public' then array(select group_id from public.group_members where user_id = p_user)
    when 'groups' then array(
      select s.group_id from public.lift_group_shares s
      join public.group_members m on m.group_id = s.group_id and m.user_id = p_user
      where s.lift_id = p_lift
    )
    else '{}'::uuid[]
  end
$$;

create function public.submit_lift(
  p_exercise_id uuid,
  p_weight numeric,
  p_unit public.weight_unit,
  p_reps integer,
  p_performed_at timestamptz default null,
  p_visibility public.lift_visibility default null,
  p_group_ids uuid[] default '{}',
  p_notes text default null,
  p_idempotency_key uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_ex public.exercises%rowtype;
  v_weight_kg numeric;
  v_score numeric;
  v_ranked boolean;
  v_vis public.lift_visibility;
  v_performed timestamptz := coalesce(p_performed_at, now());
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
  v_existing uuid;
  v_prev_best numeric;
  v_had_any boolean;
  v_lift_id uuid;
  v_groups uuid[];
  v_in_friends boolean;
  v_before jsonb;
  v_after jsonb;
  v_is_pr boolean;
  v_group uuid;
  v_sync jsonb;
  v_champion_of jsonb := '[]'::jsonb;
  v_passed jsonb := '[]'::jsonb;
  v_rec record;
  v_top_passed uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.profiles where id = v_uid and username is not null) then
    raise exception 'onboarding_required';
  end if;

  -- Serialize one user's submissions so dedupe and idempotency are race-free.
  perform pg_advisory_xact_lock(hashtext('submit:' || v_uid));

  select * into v_ex from public.exercises where id = p_exercise_id and is_active;
  if not found then raise exception 'invalid_exercise'; end if;

  -- Validation (mirrored by the Zod schema in src/lib/validation.ts).
  if v_ex.ranking_method = 'max_reps' then
    if p_weight is not null then raise exception 'weight_not_allowed'; end if;
    if p_reps is null or p_reps < 1 or p_reps > 200 then raise exception 'invalid_reps'; end if;
  else
    if p_weight is null or p_weight <= 0 or p_weight <> round(p_weight, 2) then raise exception 'invalid_weight'; end if;
    if p_unit is null then raise exception 'invalid_unit'; end if;
    if p_reps is null or p_reps < 1 or p_reps > 50 then raise exception 'invalid_reps'; end if;
    v_weight_kg := case when p_unit = 'kg' then p_weight else p_weight * 0.45359237 end;
    if v_weight_kg > v_ex.max_weight_kg then raise exception 'weight_too_high'; end if;
  end if;
  if v_performed > now() + interval '5 minutes' then raise exception 'future_date'; end if;
  if v_performed < now() - interval '5 years' then raise exception 'date_too_old'; end if;
  if v_notes is not null and char_length(v_notes) > 280 then raise exception 'notes_too_long'; end if;

  v_vis := coalesce(
    p_visibility,
    (select default_visibility from public.user_settings where user_id = v_uid),
    'public'
  );
  if v_vis = 'groups' then
    if coalesce(cardinality(p_group_ids), 0) = 0 then raise exception 'groups_required'; end if;
    if exists (
      select 1 from unnest(p_group_ids) g(id)
      where not public._member(g.id, v_uid)
    ) then
      raise exception 'not_a_member';
    end if;
  end if;

  -- Idempotency key, then a 10-minute duplicate window.
  if p_idempotency_key is not null then
    select id into v_existing from public.lifts where user_id = v_uid and idempotency_key = p_idempotency_key;
  end if;
  if v_existing is null then
    select id into v_existing
    from public.lifts
    where user_id = v_uid and exercise_id = p_exercise_id and deleted_at is null
      and reps = p_reps and weight_kg is not distinct from v_weight_kg
      and created_at > now() - interval '10 minutes'
    order by created_at desc
    limit 1;
  end if;
  if v_existing is not null then
    select l.score, l.is_ranked, l.visibility into v_score, v_ranked, v_vis from public.lifts l where l.id = v_existing;
    v_groups := public._lift_groups(v_uid, v_existing, v_vis);
    v_after := public._my_board_positions(v_uid, p_exercise_id, v_vis in ('public', 'friends'), v_groups);
    return jsonb_build_object(
      'lift_id', v_existing, 'duplicate', true, 'is_pr', false, 'is_first', false,
      'score', v_score, 'is_ranked', v_ranked, 'previous_best', null,
      'boards', v_after, 'boards_before', v_after, 'passed', '[]'::jsonb, 'champion_of', '[]'::jsonb
    );
  end if;

  select s.score, s.is_ranked into v_score, v_ranked
  from public.compute_score(v_ex.ranking_method, v_weight_kg, p_reps) s;

  -- Where will this lift appear?
  v_in_friends := v_vis in ('public', 'friends');
  v_groups := case v_vis
    when 'public' then array(select group_id from public.group_members where user_id = v_uid)
    when 'groups' then array(select distinct g from unnest(p_group_ids) g)
    else '{}'::uuid[]
  end;

  select max(score) into v_prev_best
  from public.lifts
  where user_id = v_uid and exercise_id = p_exercise_id and is_ranked and deleted_at is null;
  v_had_any := exists (
    select 1 from public.lifts where user_id = v_uid and exercise_id = p_exercise_id and deleted_at is null
  );
  v_before := public._my_board_positions(v_uid, p_exercise_id, v_in_friends, v_groups);

  insert into public.lifts (
    user_id, exercise_id, entered_weight, entered_unit, weight_kg, reps, weight_convention,
    score, is_ranked, performed_at, visibility, flagged_for_review, notes, idempotency_key
  ) values (
    v_uid, p_exercise_id,
    case when v_weight_kg is null then null else p_weight end,
    case when v_weight_kg is null then null else p_unit end,
    v_weight_kg, p_reps, v_ex.weight_convention,
    v_score, v_ranked, v_performed, v_vis,
    coalesce(v_weight_kg > v_ex.flag_threshold_kg, false),
    v_notes, p_idempotency_key
  )
  returning id into v_lift_id;

  if v_vis = 'groups' then
    insert into public.lift_group_shares (lift_id, group_id)
    select v_lift_id, g from unnest(v_groups) g;
  end if;

  v_after := public._my_board_positions(v_uid, p_exercise_id, v_in_friends, v_groups);
  v_is_pr := v_ranked and v_prev_best is not null and v_score > v_prev_best;

  -- Champions on every group board this lift touches.
  foreach v_group in array v_groups loop
    v_sync := public._sync_group_champion(v_group, p_exercise_id);
    if (v_sync->>'changed')::boolean and (v_sync->>'champion_user_id')::uuid = v_uid then
      v_champion_of := v_champion_of || jsonb_build_object(
        'group_id', v_group, 'group_name', (select name from public.groups where id = v_group)
      );
      insert into public.activities (actor_id, type, lift_id, group_id, exercise_id)
      values (v_uid, 'first_place', v_lift_id, v_group, p_exercise_id);

      if (v_sync->>'previous_user_id') is not null
         and (v_sync->>'previous_user_id')::uuid <> v_uid
         and coalesce((select notify_first_place from public.user_settings
                       where user_id = (v_sync->>'previous_user_id')::uuid), true)
         and not public._blocked(v_uid, (v_sync->>'previous_user_id')::uuid) then
        insert into public.notifications (recipient_id, actor_id, type, group_id, exercise_id, lift_id)
        values ((v_sync->>'previous_user_id')::uuid, v_uid, 'first_place', v_group, p_exercise_id, v_lift_id);
      end if;
    end if;
  end loop;

  -- "You passed someone": only people who can see this lift, compared by score.
  if v_ranked and (v_prev_best is null or v_score > v_prev_best) and v_vis <> 'private' then
    for v_rec in
      with audience as (
        select case when f.requester_id = v_uid then f.addressee_id else f.requester_id end as id
        from public.friendships f
        where v_in_friends and f.status = 'accepted' and v_uid in (f.requester_id, f.addressee_id)
        union
        select m.user_id from public.group_members m where m.group_id = any (v_groups)
      )
      select a.id as recipient_id, pr.username,
             (select max(l.score) from public.lifts l
               where l.user_id = a.id and l.exercise_id = p_exercise_id and l.is_ranked
                 and l.deleted_at is null and l.visibility <> 'private') as their_best
      from audience a
      join public.profiles pr on pr.id = a.id
      where a.id <> v_uid and not public._blocked(v_uid, a.id)
    loop
      continue when v_rec.their_best is null;
      continue when not (v_score > v_rec.their_best and (v_prev_best is null or v_prev_best <= v_rec.their_best));
      v_passed := v_passed || jsonb_build_object(
        'user_id', v_rec.recipient_id, 'username', v_rec.username, 'their_best', v_rec.their_best
      );
      if coalesce((select notify_passed from public.user_settings where user_id = v_rec.recipient_id), true)
         and not exists (
           select 1 from public.notifications n
           where n.recipient_id = v_rec.recipient_id and n.actor_id = v_uid and n.type = 'passed'
             and n.exercise_id = p_exercise_id and n.created_at > now() - interval '24 hours'
         ) then
        insert into public.notifications (recipient_id, actor_id, type, exercise_id, lift_id)
        values (v_rec.recipient_id, v_uid, 'passed', p_exercise_id, v_lift_id);
      end if;
    end loop;
  end if;

  if v_vis <> 'private' then
    if v_is_pr then
      insert into public.activities (actor_id, type, lift_id, exercise_id)
      values (v_uid, 'pr', v_lift_id, p_exercise_id);
    end if;
    if jsonb_array_length(v_passed) > 0 then
      select (p->>'user_id')::uuid into v_top_passed
      from jsonb_array_elements(v_passed) p
      order by (p->>'their_best')::numeric desc
      limit 1;
      insert into public.activities (actor_id, type, lift_id, exercise_id, target_user_id)
      values (v_uid, 'passed', v_lift_id, p_exercise_id, v_top_passed);
    end if;
  end if;

  return jsonb_build_object(
    'lift_id', v_lift_id,
    'duplicate', false,
    'is_pr', v_is_pr,
    'is_first', not v_had_any,
    'score', v_score,
    'is_ranked', v_ranked,
    'previous_best', v_prev_best,
    'boards_before', v_before,
    'boards', v_after,
    'passed', (select coalesce(jsonb_agg(p - 'their_best'), '[]'::jsonb) from jsonb_array_elements(v_passed) p),
    'champion_of', v_champion_of
  );
end;
$$;

-- ───────────── Lift edits ─────────────
-- Weight, reps, exercise and date are immutable; delete and re-log instead.
create function public.update_lift_sharing(
  p_lift_id uuid,
  p_visibility public.lift_visibility,
  p_group_ids uuid[] default '{}',
  p_notes text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_lift public.lifts%rowtype;
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_lift from public.lifts where id = p_lift_id and user_id = v_uid and deleted_at is null for update;
  if not found then raise exception 'not_found'; end if;
  if v_notes is not null and char_length(v_notes) > 280 then raise exception 'notes_too_long'; end if;
  if p_visibility = 'groups' then
    if coalesce(cardinality(p_group_ids), 0) = 0 then raise exception 'groups_required'; end if;
    if exists (select 1 from unnest(p_group_ids) g(id) where not public._member(g.id, v_uid)) then
      raise exception 'not_a_member';
    end if;
  end if;

  update public.lifts set visibility = p_visibility, notes = v_notes where id = p_lift_id;
  delete from public.lift_group_shares where lift_id = p_lift_id;
  if p_visibility = 'groups' then
    insert into public.lift_group_shares (lift_id, group_id)
    select p_lift_id, g from (select distinct unnest(p_group_ids) g) s;
  end if;

  perform public._sync_user_groups(v_uid, v_lift.exercise_id);
end;
$$;

create function public.delete_lift(p_lift_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_exercise uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  update public.lifts set deleted_at = now()
  where id = p_lift_id and user_id = v_uid and deleted_at is null
  returning exercise_id into v_exercise;
  if v_exercise is null then raise exception 'not_found'; end if;
  perform public._sync_user_groups(v_uid, v_exercise);
end;
$$;

-- ───────────── Lift reads ─────────────
-- Best visible ranked lift per exercise for a user (their PRs as the viewer may see them).
create function public.get_prs(p_user_id uuid default null)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'exercise_id', b.exercise_id, 'exercise_name', e.name, 'exercise_slug', e.slug,
    'ranking_method', e.ranking_method, 'lift_id', b.id, 'entered_weight', b.entered_weight,
    'entered_unit', b.entered_unit, 'weight_kg', b.weight_kg, 'reps', b.reps, 'score', b.score,
    'performed_at', b.performed_at, 'verification_status', b.verification_status
  ) order by b.performed_at desc), '[]'::jsonb)
  from (
    select distinct on (l.exercise_id) l.*
    from public.lifts l
    where auth.uid() is not null
      and l.user_id = coalesce(p_user_id, auth.uid())
      and l.is_ranked and l.deleted_at is null
      and public._can_view_lift(auth.uid(), l.id, l.user_id, l.visibility)
    order by l.exercise_id, l.score desc, l.weight_kg desc nulls last, l.performed_at, l.created_at, l.id
  ) b
  join public.exercises e on e.id = b.exercise_id
$$;

-- Everything the Add Lift screen needs to prefill in one call.
create function public.get_lift_defaults()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'last', (
      select jsonb_build_object('exercise_id', l.exercise_id, 'entered_weight', l.entered_weight,
                                'entered_unit', l.entered_unit, 'reps', l.reps)
      from public.lifts l where l.user_id = auth.uid() and l.deleted_at is null
      order by l.created_at desc limit 1
    ),
    'last_by_exercise', (
      select coalesce(jsonb_object_agg(x.exercise_id, jsonb_build_object(
        'entered_weight', x.entered_weight, 'entered_unit', x.entered_unit, 'reps', x.reps)), '{}'::jsonb)
      from (
        select distinct on (l.exercise_id) l.exercise_id, l.entered_weight, l.entered_unit, l.reps
        from public.lifts l where l.user_id = auth.uid() and l.deleted_at is null
        order by l.exercise_id, l.created_at desc
      ) x
    ),
    'recent_exercise_ids', (
      select coalesce(jsonb_agg(r.exercise_id order by r.last_used desc), '[]'::jsonb)
      from (
        select l.exercise_id, max(l.created_at) as last_used
        from public.lifts l where l.user_id = auth.uid() and l.deleted_at is null
        group by l.exercise_id order by 2 desc limit 8
      ) r
    ),
    'favorite_exercise_ids', (
      select coalesce(jsonb_agg(f.exercise_id), '[]'::jsonb)
      from public.favorite_exercises f where f.user_id = auth.uid()
    ),
    'preferred_unit', (select preferred_unit from public.profiles where id = auth.uid()),
    'default_visibility', (select default_visibility from public.user_settings where user_id = auth.uid()),
    'groups', (
      select coalesce(jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name) order by g.name), '[]'::jsonb)
      from public.groups g join public.group_members m on m.group_id = g.id and m.user_id = auth.uid()
    )
  )
  where auth.uid() is not null
$$;

-- ───────────── Grants ─────────────
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function
  public.can_view_lift(uuid, uuid, public.lift_visibility),
  public.is_blocked_with_me(uuid),
  public.am_group_member(uuid),
  public.am_group_admin(uuid),
  public.app_timezone(),
  public.is_reserved_username(text),
  public.compute_score(public.ranking_method, numeric, integer),
  public.get_leaderboard(uuid, text, uuid, text, integer, integer),
  public.submit_lift(uuid, numeric, public.weight_unit, integer, timestamptz, public.lift_visibility, uuid[], text, uuid),
  public.update_lift_sharing(uuid, public.lift_visibility, uuid[], text),
  public.delete_lift(uuid),
  public.get_prs(uuid),
  public.get_lift_defaults()
to authenticated;


-- ===== 20261011000500_social.sql =====
-- LiftRank 0005 — profiles, groups, invites, friends, blocks, notifications, feed, home.

-- ───────────── Profiles ─────────────
create function public.complete_username(p_username text, p_display_name text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_username text := lower(btrim(coalesce(p_username, '')));
  v_display text := nullif(btrim(coalesce(p_display_name, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if v_username !~ '^[a-z0-9_]{3,20}$' then raise exception 'username_invalid'; end if;
  if public.is_reserved_username(v_username) then raise exception 'username_reserved'; end if;
  if v_display is not null and char_length(v_display) > 40 then raise exception 'display_name_too_long'; end if;
  if exists (select 1 from public.profiles where username = v_username and id <> v_uid) then
    raise exception 'username_taken';
  end if;
  update public.profiles
  set username = v_username,
      display_name = coalesce(v_display, display_name, v_username),
      onboarded_at = coalesce(onboarded_at, now())
  where id = v_uid;
exception
  when unique_violation then raise exception 'username_taken';
end;
$$;

create function public.update_my_profile(
  p_display_name text,
  p_bio text,
  p_preferred_unit public.weight_unit,
  p_profile_visibility public.profile_visibility
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_display text := nullif(btrim(coalesce(p_display_name, '')), '');
  v_bio text := nullif(btrim(coalesce(p_bio, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if v_display is not null and char_length(v_display) > 40 then raise exception 'display_name_too_long'; end if;
  if v_bio is not null and char_length(v_bio) > 160 then raise exception 'bio_too_long'; end if;
  update public.profiles
  set display_name = coalesce(v_display, username),
      bio = v_bio,
      preferred_unit = coalesce(p_preferred_unit, preferred_unit),
      profile_visibility = coalesce(p_profile_visibility, profile_visibility)
  where id = v_uid;
end;
$$;

create function public.get_my_profile()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', p.id, 'username', p.username, 'display_name', p.display_name, 'avatar_path', p.avatar_path,
    'bio', p.bio, 'preferred_unit', p.preferred_unit, 'profile_visibility', p.profile_visibility,
    'public_leaderboard_opt_in', p.public_leaderboard_opt_in, 'onboarded_at', p.onboarded_at,
    'created_at', p.created_at,
    'settings', to_jsonb(s) - 'user_id' - 'updated_at'
  )
  from public.profiles p
  left join public.user_settings s on s.user_id = p.id
  where p.id = auth.uid()
$$;

create function public._relationship(p_me uuid, p_other uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_me = p_other then 'self'
    when exists (select 1 from public.blocks where blocker_id = p_me and blocked_id = p_other) then 'blocked'
    else coalesce((
      select case
        when f.status = 'accepted' then 'friends'
        when f.requester_id = p_me then 'outgoing'
        else 'incoming'
      end
      from public.friendships f
      where least(f.requester_id, f.addressee_id) = least(p_me, p_other)
        and greatest(f.requester_id, f.addressee_id) = greatest(p_me, p_other)
    ), 'none')
  end
$$;

-- Another user's profile as the caller may see it. Null when missing or blocked either way.
create function public.get_profile(p_username text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_p public.profiles%rowtype;
  v_rel text;
  v_details boolean;
  v_featured uuid[];
  v_friendship uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  select * into v_p from public.profiles where username = lower(p_username);
  if not found then return null; end if;
  if v_p.id <> v_uid and exists (
    select 1 from public.blocks where blocker_id = v_p.id and blocked_id = v_uid
  ) then
    return null;
  end if;

  v_rel := public._relationship(v_uid, v_p.id);
  v_details := v_rel <> 'blocked' and (
    v_p.id = v_uid
    or v_p.profile_visibility = 'public'
    or (v_p.profile_visibility = 'friends' and v_rel = 'friends')
  );
  select featured_exercise_ids into v_featured from public.user_settings where user_id = v_p.id;
  select f.id into v_friendship from public.friendships f
  where least(f.requester_id, f.addressee_id) = least(v_uid, v_p.id)
    and greatest(f.requester_id, f.addressee_id) = greatest(v_uid, v_p.id);

  return jsonb_build_object(
    'id', v_p.id, 'username', v_p.username, 'display_name', v_p.display_name,
    'avatar_path', v_p.avatar_path, 'created_at', v_p.created_at,
    'relationship', v_rel, 'friendship_id', v_friendship,
    'can_see_details', v_details,
    'bio', case when v_details then v_p.bio end,
    'featured_exercise_ids', case when v_details then to_jsonb(coalesce(v_featured, '{}')) else '[]'::jsonb end,
    'prs', case when v_details and v_rel <> 'blocked' then public.get_prs(v_p.id) else '[]'::jsonb end,
    'friend_count', (select count(*) from public.friendships f
                     where f.status = 'accepted' and v_p.id in (f.requester_id, f.addressee_id))
  );
end;
$$;

-- ───────────── Groups ─────────────
create function public.create_group(p_name text, p_description text default null)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_name text := btrim(coalesce(p_name, ''));
  v_desc text := nullif(btrim(coalesce(p_description, '')), '');
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.profiles where id = v_uid and username is not null) then
    raise exception 'onboarding_required';
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 50 then raise exception 'group_name_invalid'; end if;
  if v_desc is not null and char_length(v_desc) > 280 then raise exception 'description_too_long'; end if;
  if (select count(*) from public.group_members where user_id = v_uid and role = 'owner') >= 20 then
    raise exception 'too_many_groups';
  end if;
  insert into public.groups (name, description, created_by) values (v_name, v_desc, v_uid) returning id into v_id;
  insert into public.group_members (group_id, user_id, role) values (v_id, v_uid, 'owner');
  return v_id;
end;
$$;

create function public.update_group(p_group_id uuid, p_name text, p_description text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_name text := btrim(coalesce(p_name, ''));
  v_desc text := nullif(btrim(coalesce(p_description, '')), '');
begin
  if not public.am_group_admin(p_group_id) then raise exception 'forbidden'; end if;
  if char_length(v_name) < 2 or char_length(v_name) > 50 then raise exception 'group_name_invalid'; end if;
  if v_desc is not null and char_length(v_desc) > 280 then raise exception 'description_too_long'; end if;
  update public.groups set name = v_name, description = v_desc where id = p_group_id;
end;
$$;

create function public.delete_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(public._role(p_group_id, auth.uid()) <> 'owner', true) then raise exception 'forbidden'; end if;
  delete from public.groups where id = p_group_id;
end;
$$;

create function public.get_my_groups()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', g.id, 'name', g.name, 'description', g.description, 'avatar_path', g.avatar_path,
    'role', m.role,
    'member_count', (select count(*) from public.group_members x where x.group_id = g.id),
    'champion_count', (select count(*) from public.record_history rh
                       where rh.group_id = g.id and rh.until is null and rh.user_id = auth.uid())
  ) order by g.name), '[]'::jsonb)
  from public.groups g
  join public.group_members m on m.group_id = g.id and m.user_id = auth.uid()
$$;

create function public.get_group(p_group_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null or not public._member(p_group_id, v_uid) then return null; end if;
  return (
    select jsonb_build_object(
      'id', g.id, 'name', g.name, 'description', g.description, 'avatar_path', g.avatar_path,
      'created_at', g.created_at,
      'my_role', public._role(g.id, v_uid),
      'members', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'username', p.username, 'display_name', p.display_name,
          'avatar_path', p.avatar_path, 'role', m.role, 'joined_at', m.joined_at,
          'hidden', public._blocked(v_uid, m.user_id)
        ) order by case m.role when 'owner' then 0 when 'admin' then 1 else 2 end, m.joined_at), '[]'::jsonb)
        from public.group_members m join public.profiles p on p.id = m.user_id
        where m.group_id = g.id
      ),
      'champions', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'exercise_id', e.id, 'exercise_name', e.name, 'ranking_method', e.ranking_method,
          'user_id', rh.user_id, 'username', p.username, 'display_name', p.display_name,
          'since', rh.since, 'entered_weight', l.entered_weight, 'entered_unit', l.entered_unit,
          'weight_kg', l.weight_kg, 'reps', l.reps, 'score', l.score
        ) order by e.popular_rank, e.name), '[]'::jsonb)
        from public.record_history rh
        join public.exercises e on e.id = rh.exercise_id
        left join public.profiles p on p.id = rh.user_id
        left join public.lifts l on l.id = rh.lift_id
        where rh.group_id = g.id and rh.until is null
          and (rh.user_id is null or not public._blocked(v_uid, rh.user_id))
      ),
      'board_exercises', (
        select coalesce(jsonb_agg(jsonb_build_object('exercise_id', x.id, 'exercise_name', x.name, 'lifters', x.lifters)
          order by x.lifters desc, x.name), '[]'::jsonb)
        from (
          select e.id, e.name, count(distinct l.user_id) as lifters
          from public.lifts l
          join public.group_members m on m.user_id = l.user_id and m.group_id = g.id
          join public.exercises e on e.id = l.exercise_id
          where l.is_ranked and l.deleted_at is null
            and (l.visibility = 'public' or (l.visibility = 'groups' and exists (
              select 1 from public.lift_group_shares s where s.lift_id = l.id and s.group_id = g.id)))
          group by e.id, e.name
        ) x
      ),
      'invites', case when public._role(g.id, v_uid) in ('owner', 'admin') then (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', i.id, 'created_at', i.created_at, 'expires_at', i.expires_at,
          'max_uses', i.max_uses, 'use_count', i.use_count
        ) order by i.created_at desc), '[]'::jsonb)
        from public.group_invites i
        where i.group_id = g.id and i.revoked_at is null and i.expires_at > now()
          and (i.max_uses is null or i.use_count < i.max_uses)
      ) else '[]'::jsonb end
    )
    from public.groups g where g.id = p_group_id
  );
end;
$$;

create function public.leave_group(p_group_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_role public.group_role := public._role(p_group_id, auth.uid());
begin
  if v_role is null then raise exception 'not_a_member'; end if;
  if v_role = 'owner' then raise exception 'owner_must_transfer'; end if;
  delete from public.group_members where group_id = p_group_id and user_id = v_uid;
  perform public._sync_group_all(p_group_id);
end;
$$;

create function public.remove_group_member(p_group_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_my_role public.group_role := public._role(p_group_id, auth.uid());
  v_their_role public.group_role := public._role(p_group_id, p_user_id);
begin
  if v_their_role is null then raise exception 'not_a_member'; end if;
  if p_user_id = auth.uid() then raise exception 'use_leave'; end if;
  if v_my_role is null or v_my_role = 'member'
     or v_their_role = 'owner'
     or (v_my_role = 'admin' and v_their_role = 'admin') then
    raise exception 'forbidden';
  end if;
  delete from public.group_members where group_id = p_group_id and user_id = p_user_id;
  perform public._sync_group_all(p_group_id);
end;
$$;

-- Owner only. p_role = 'owner' transfers ownership (the old owner becomes admin).
create function public.set_group_member_role(p_group_id uuid, p_user_id uuid, p_role public.group_role)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if coalesce(public._role(p_group_id, v_uid) <> 'owner', true) then raise exception 'forbidden'; end if;
  if p_user_id = v_uid then raise exception 'forbidden'; end if;
  if not public._member(p_group_id, p_user_id) then raise exception 'not_a_member'; end if;
  if p_role = 'owner' then
    update public.group_members set role = 'admin' where group_id = p_group_id and user_id = v_uid;
    update public.group_members set role = 'owner' where group_id = p_group_id and user_id = p_user_id;
  else
    update public.group_members set role = p_role where group_id = p_group_id and user_id = p_user_id;
  end if;
end;
$$;

-- ───────────── Invites ─────────────
-- Tokens are 32 random bytes (64 hex chars). Only their SHA-256 is stored.
create function public.create_group_invite(
  p_group_id uuid, p_expires_in_days integer default 7, p_max_uses integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_token text := encode(extensions.gen_random_bytes(32), 'hex');
  v_id uuid;
  v_expires timestamptz;
begin
  if not public.am_group_admin(p_group_id) then raise exception 'forbidden'; end if;
  if p_expires_in_days is null or p_expires_in_days < 1 or p_expires_in_days > 30 then
    raise exception 'invalid_expiry';
  end if;
  if p_max_uses is not null and (p_max_uses < 1 or p_max_uses > 200) then raise exception 'invalid_max_uses'; end if;
  if (select count(*) from public.group_invites
      where group_id = p_group_id and revoked_at is null and expires_at > now()) >= 20 then
    raise exception 'too_many_invites';
  end if;
  v_expires := now() + make_interval(days => p_expires_in_days);
  insert into public.group_invites (group_id, token_hash, created_by, expires_at, max_uses)
  values (p_group_id, extensions.digest(v_token, 'sha256'), auth.uid(), v_expires, p_max_uses)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'token', v_token, 'expires_at', v_expires);
end;
$$;

create function public.revoke_group_invite(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_group uuid;
begin
  select group_id into v_group from public.group_invites where id = p_invite_id;
  if v_group is null or not public.am_group_admin(v_group) then raise exception 'forbidden'; end if;
  update public.group_invites set revoked_at = now() where id = p_invite_id and revoked_at is null;
end;
$$;

create function public._invite_by_token(p_token text)
returns public.group_invites
language sql
stable
security definer
set search_path = ''
as $$
  select * from public.group_invites
  where p_token ~ '^[0-9a-f]{64}$' and token_hash = extensions.digest(p_token, 'sha256')
$$;

-- Callable while signed out so the invite page can show the group name.
create function public.get_invite_preview(p_token text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_inv public.group_invites;
  v_reason text;
begin
  v_inv := public._invite_by_token(p_token);
  if v_inv.id is null then return jsonb_build_object('valid', false, 'reason', 'not_found'); end if;
  v_reason := case
    when v_inv.revoked_at is not null then 'revoked'
    when v_inv.expires_at <= now() then 'expired'
    when v_inv.max_uses is not null and v_inv.use_count >= v_inv.max_uses then 'used_up'
    when (select count(*) from public.group_members where group_id = v_inv.group_id) >= 200 then 'group_full'
  end;
  return (
    select jsonb_build_object(
      'valid', v_reason is null,
      'reason', v_reason,
      'group_id', case when v_reason is null then g.id end,
      'group_name', case when v_reason is null then g.name end,
      'member_count', case when v_reason is null then
        (select count(*) from public.group_members m where m.group_id = g.id) end,
      'is_member', auth.uid() is not null and public._member(g.id, auth.uid())
    )
    from public.groups g where g.id = v_inv.group_id
  );
end;
$$;

create function public.accept_group_invite(p_token text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_inv public.group_invites;
  v_admin uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from public.profiles where id = v_uid and username is not null) then
    raise exception 'onboarding_required';
  end if;
  v_inv := public._invite_by_token(p_token);
  if v_inv.id is null then raise exception 'invite_invalid'; end if;
  perform pg_advisory_xact_lock(hashtext('group:' || v_inv.group_id));
  if public._member(v_inv.group_id, v_uid) then return v_inv.group_id; end if;

  select * into v_inv from public.group_invites where id = v_inv.id for update;
  if v_inv.revoked_at is not null or v_inv.expires_at <= now()
     or (v_inv.max_uses is not null and v_inv.use_count >= v_inv.max_uses) then
    raise exception 'invite_invalid';
  end if;
  if (select count(*) from public.group_members where group_id = v_inv.group_id) >= 200 then
    raise exception 'group_full';
  end if;
  if exists (
    select 1 from public.group_members m
    where m.group_id = v_inv.group_id and m.role = 'owner' and public._blocked(m.user_id, v_uid)
  ) then
    raise exception 'invite_invalid';
  end if;

  insert into public.group_members (group_id, user_id, role) values (v_inv.group_id, v_uid, 'member');
  update public.group_invites set use_count = use_count + 1 where id = v_inv.id;

  insert into public.activities (actor_id, type, group_id) values (v_uid, 'joined_group', v_inv.group_id);
  for v_admin in
    select m.user_id from public.group_members m
    join public.user_settings s on s.user_id = m.user_id
    where m.group_id = v_inv.group_id and m.role in ('owner', 'admin') and m.user_id <> v_uid
      and s.notify_group_joins and not public._blocked(m.user_id, v_uid)
  loop
    insert into public.notifications (recipient_id, actor_id, type, group_id)
    values (v_admin, v_uid, 'group_joined', v_inv.group_id);
  end loop;

  perform public._sync_group_all(v_inv.group_id);
  return v_inv.group_id;
end;
$$;

-- ───────────── Friends & blocks ─────────────
create function public.search_users(p_query text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', p.id, 'username', p.username, 'display_name', p.display_name, 'avatar_path', p.avatar_path,
    'relationship', public._relationship(auth.uid(), p.id)
  ) order by (p.username = lower(btrim(p_query))) desc, p.username), '[]'::jsonb)
  from (
    select * from public.profiles p
    where auth.uid() is not null
      and char_length(btrim(coalesce(p_query, ''))) >= 2
      and p.username is not null
      and p.id <> auth.uid()
      and not public._blocked(auth.uid(), p.id)
      and (
        starts_with(p.username, lower(btrim(p_query)))
        or starts_with(lower(coalesce(p.display_name, '')), lower(btrim(p_query)))
      )
    order by p.username
    limit 20
  ) p
$$;

create function public.send_friend_request(p_user_id uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_f public.friendships%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_user_id is null or p_user_id = v_uid then raise exception 'invalid_user'; end if;
  if not exists (select 1 from public.profiles where id = p_user_id and username is not null) then
    raise exception 'invalid_user';
  end if;
  if public._blocked(v_uid, p_user_id) then raise exception 'invalid_user'; end if;

  select * into v_f from public.friendships
  where least(requester_id, addressee_id) = least(v_uid, p_user_id)
    and greatest(requester_id, addressee_id) = greatest(v_uid, p_user_id)
  for update;

  if found then
    if v_f.status = 'accepted' then return 'friends'; end if;
    if v_f.requester_id = v_uid then return 'outgoing'; end if;
    -- They already asked us: accept.
    perform public.respond_friend_request(v_f.id, true);
    return 'friends';
  end if;

  if (select count(*) from public.friendships where requester_id = v_uid and status = 'pending') >= 100 then
    raise exception 'too_many_requests';
  end if;

  insert into public.friendships (requester_id, addressee_id) values (v_uid, p_user_id) returning id into v_id;
  if coalesce((select notify_friend_requests from public.user_settings where user_id = p_user_id), true) then
    insert into public.notifications (recipient_id, actor_id, type, friendship_id)
    values (p_user_id, v_uid, 'friend_request', v_id);
  end if;
  return 'outgoing';
end;
$$;

create function public.respond_friend_request(p_friendship_id uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_f public.friendships%rowtype;
begin
  select * into v_f from public.friendships where id = p_friendship_id and addressee_id = v_uid and status = 'pending';
  if not found then raise exception 'not_found'; end if;
  if p_accept then
    update public.friendships set status = 'accepted', responded_at = now() where id = p_friendship_id;
    delete from public.notifications where friendship_id = p_friendship_id and type = 'friend_request';
    if coalesce((select notify_friend_requests from public.user_settings where user_id = v_f.requester_id), true) then
      insert into public.notifications (recipient_id, actor_id, type, friendship_id)
      values (v_f.requester_id, v_uid, 'friend_accepted', p_friendship_id);
    end if;
  else
    delete from public.friendships where id = p_friendship_id;
  end if;
end;
$$;

create function public.cancel_friend_request(p_friendship_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.friendships
  where id = p_friendship_id and requester_id = auth.uid() and status = 'pending';
  if not found then raise exception 'not_found'; end if;
end;
$$;

create function public.remove_friend(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.friendships
  where status = 'accepted'
    and least(requester_id, addressee_id) = least(auth.uid(), p_user_id)
    and greatest(requester_id, addressee_id) = greatest(auth.uid(), p_user_id);
end;
$$;

create function public.block_user(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;
  if p_user_id is null or p_user_id = v_uid then raise exception 'invalid_user'; end if;
  insert into public.blocks (blocker_id, blocked_id) values (v_uid, p_user_id) on conflict do nothing;
  delete from public.friendships
  where least(requester_id, addressee_id) = least(v_uid, p_user_id)
    and greatest(requester_id, addressee_id) = greatest(v_uid, p_user_id);
end;
$$;

create function public.unblock_user(p_user_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.blocks where blocker_id = auth.uid() and blocked_id = p_user_id
$$;

create function public.get_friends()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with mine as (
    select f.*, case when f.requester_id = auth.uid() then f.addressee_id else f.requester_id end as other_id
    from public.friendships f
    where auth.uid() in (f.requester_id, f.addressee_id)
  ),
  people as (
    select m.*, jsonb_build_object(
      'friendship_id', m.id, 'user_id', p.id, 'username', p.username,
      'display_name', p.display_name, 'avatar_path', p.avatar_path, 'since', coalesce(m.responded_at, m.created_at)
    ) as j
    from mine m join public.profiles p on p.id = m.other_id
  )
  select jsonb_build_object(
    'friends', coalesce((select jsonb_agg(j order by j->>'username') from people where status = 'accepted'), '[]'::jsonb),
    'incoming', coalesce((select jsonb_agg(j order by created_at desc) from people
                          where status = 'pending' and addressee_id = auth.uid()), '[]'::jsonb),
    'outgoing', coalesce((select jsonb_agg(j order by created_at desc) from people
                          where status = 'pending' and requester_id = auth.uid()), '[]'::jsonb),
    'blocked', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', p.id, 'username', p.username, 'display_name', p.display_name)
                       order by p.username)
      from public.blocks b join public.profiles p on p.id = b.blocked_id
      where b.blocker_id = auth.uid()
    ), '[]'::jsonb)
  )
  where auth.uid() is not null
$$;

-- ───────────── Notifications ─────────────
-- Visibility is re-checked at read time: a notification about a lift the
-- recipient can no longer see (private, deleted, blocked) is not returned.
create function public._visible_notifications(p_user uuid)
returns setof public.notifications
language sql
stable
security definer
set search_path = ''
as $$
  select n.*
  from public.notifications n
  left join public.lifts l on l.id = n.lift_id
  where n.recipient_id = p_user
    and (n.actor_id is null or not public._blocked(p_user, n.actor_id))
    and (n.lift_id is null or (
      l.deleted_at is null and public._can_view_lift(p_user, l.id, l.user_id, l.visibility)
    ))
    and (n.group_id is null or public._member(n.group_id, p_user))
$$;

create function public.get_notifications(p_limit integer default 50)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', n.id, 'type', n.type, 'created_at', n.created_at, 'read_at', n.read_at,
    'actor', case when a.id is null then null else jsonb_build_object(
      'id', a.id, 'username', a.username, 'display_name', a.display_name, 'avatar_path', a.avatar_path) end,
    'group', case when g.id is null then null else jsonb_build_object('id', g.id, 'name', g.name) end,
    'exercise', case when e.id is null then null else jsonb_build_object(
      'id', e.id, 'name', e.name, 'ranking_method', e.ranking_method) end,
    'lift', case when l.id is null then null else jsonb_build_object(
      'id', l.id, 'entered_weight', l.entered_weight, 'entered_unit', l.entered_unit,
      'weight_kg', l.weight_kg, 'reps', l.reps, 'score', l.score) end,
    'friendship_id', n.friendship_id,
    'friendship_pending', exists (select 1 from public.friendships f where f.id = n.friendship_id and f.status = 'pending')
  ) order by n.created_at desc), '[]'::jsonb)
  from (
    select * from public._visible_notifications(auth.uid())
    order by created_at desc
    limit least(greatest(coalesce(p_limit, 50), 1), 100)
  ) n
  left join public.profiles a on a.id = n.actor_id
  left join public.groups g on g.id = n.group_id
  left join public.exercises e on e.id = n.exercise_id
  left join public.lifts l on l.id = n.lift_id
$$;

create function public.unread_notification_count()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from public._visible_notifications(auth.uid()) where read_at is null
$$;

create function public.mark_notifications_read(p_ids uuid[] default null)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.notifications set read_at = now()
  where recipient_id = auth.uid() and read_at is null
    and (p_ids is null or id = any (p_ids))
$$;

-- ───────────── Activity feed ─────────────
create function public._can_view_activity(p_viewer uuid, p_activity uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.activities a
    left join public.lifts l on l.id = a.lift_id
    where a.id = p_activity
      and p_viewer is not null
      and not public._blocked(p_viewer, a.actor_id)
      and (a.target_user_id is null or not public._blocked(p_viewer, a.target_user_id))
      and (a.lift_id is null or (l.deleted_at is null and public._can_view_lift(p_viewer, l.id, l.user_id, l.visibility)))
      and (
        a.actor_id = p_viewer
        or (a.group_id is null and public._friends(p_viewer, a.actor_id))
        or (a.group_id is not null and public._member(a.group_id, p_viewer))
      )
  )
$$;

create function public.get_feed(
  p_limit integer default 30, p_before timestamptz default null, p_group_id uuid default null,
  p_actor_id uuid default null
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'type', a.type, 'created_at', a.created_at,
    'actor', jsonb_build_object('id', ac.id, 'username', ac.username, 'display_name', ac.display_name,
                                'avatar_path', ac.avatar_path),
    'target', case when t.id is null then null else jsonb_build_object(
      'id', t.id, 'username', t.username, 'display_name', t.display_name) end,
    'group', case when g.id is null then null else jsonb_build_object('id', g.id, 'name', g.name) end,
    'exercise', case when e.id is null then null else jsonb_build_object(
      'id', e.id, 'name', e.name, 'ranking_method', e.ranking_method) end,
    'lift', case when l.id is null then null else jsonb_build_object(
      'id', l.id, 'entered_weight', l.entered_weight, 'entered_unit', l.entered_unit,
      'weight_kg', l.weight_kg, 'reps', l.reps, 'score', l.score) end,
    'reactions', (
      select coalesce(jsonb_object_agg(r.emoji, r.n), '{}'::jsonb)
      from (select emoji, count(*) n from public.activity_reactions where activity_id = a.id group by emoji) r
    ),
    'my_reactions', (
      select coalesce(jsonb_agg(emoji), '[]'::jsonb)
      from public.activity_reactions where activity_id = a.id and user_id = auth.uid()
    )
  ) order by a.created_at desc), '[]'::jsonb)
  from (
    select a.*
    from public.activities a
    where auth.uid() is not null
      and (p_before is null or a.created_at < p_before)
      and (p_group_id is null or a.group_id = p_group_id)
      and (p_actor_id is null or a.actor_id = p_actor_id)
      and (
        a.actor_id = auth.uid()
        or public._friends(auth.uid(), a.actor_id)
        or (a.group_id is not null and public._member(a.group_id, auth.uid()))
      )
      and public._can_view_activity(auth.uid(), a.id)
    order by a.created_at desc
    limit least(greatest(coalesce(p_limit, 30), 1), 100)
  ) a
  join public.profiles ac on ac.id = a.actor_id
  left join public.profiles t on t.id = a.target_user_id
  left join public.groups g on g.id = a.group_id
  left join public.exercises e on e.id = a.exercise_id
  left join public.lifts l on l.id = a.lift_id
$$;

create function public.toggle_reaction(p_activity_id uuid, p_emoji text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if not public._can_view_activity(v_uid, p_activity_id) then raise exception 'not_found'; end if;
  if p_emoji not in ('💪', '🔥', '👏') then raise exception 'invalid_reaction'; end if;
  delete from public.activity_reactions where activity_id = p_activity_id and user_id = v_uid and emoji = p_emoji;
  if found then return false; end if;
  insert into public.activity_reactions (activity_id, user_id, emoji) values (p_activity_id, v_uid, p_emoji);
  return true;
end;
$$;

-- ───────────── Home ─────────────
create function public.get_home()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_boards jsonb := '[]'::jsonb;
  v_ex record;
  v_board record;
  v_me record;
  v_above jsonb;
  v_total integer;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  for v_ex in
    select l.exercise_id, e.name, e.ranking_method, max(l.created_at) as last_logged
    from public.lifts l join public.exercises e on e.id = l.exercise_id
    where l.user_id = v_uid and l.deleted_at is null and l.is_ranked and l.visibility <> 'private'
    group by l.exercise_id, e.name, e.ranking_method
  loop
    for v_board in
      select 'friends'::text as kind, null::uuid as group_id, null::text as group_name
      union all
      select 'group', g.id, g.name
      from public.groups g join public.group_members m on m.group_id = g.id and m.user_id = v_uid
    loop
      select count(*) into v_total from public._board(v_uid, v_board.kind, v_board.group_id, v_ex.exercise_id, 'all');
      select * into v_me from public._board(v_uid, v_board.kind, v_board.group_id, v_ex.exercise_id, 'all') b
      where b.uid = v_uid;
      continue when v_me.pos is null;

      v_above := null;
      if v_me.pos > 1 then
        select jsonb_build_object(
          'user_id', b.uid, 'username', p.username, 'display_name', p.display_name,
          'avatar_path', p.avatar_path, 'rank', b.pos, 'entered_weight', b.entered_weight,
          'entered_unit', b.entered_unit, 'weight_kg', b.weight_kg, 'reps', b.reps, 'score', b.score)
        into v_above
        from public._board(v_uid, v_board.kind, v_board.group_id, v_ex.exercise_id, 'all') b
        join public.profiles p on p.id = b.uid
        where b.pos < v_me.pos and not public._blocked(v_uid, b.uid)
        order by b.pos desc limit 1;
      end if;

      v_boards := v_boards || jsonb_build_object(
        'exercise_id', v_ex.exercise_id, 'exercise_name', v_ex.name, 'ranking_method', v_ex.ranking_method,
        'kind', v_board.kind, 'group_id', v_board.group_id, 'group_name', v_board.group_name,
        'rank', v_me.pos, 'total', v_total,
        'recent', v_ex.last_logged > now() - interval '60 days',
        'me', jsonb_build_object('lift_id', v_me.lid, 'entered_weight', v_me.entered_weight,
          'entered_unit', v_me.entered_unit, 'weight_kg', v_me.weight_kg, 'reps', v_me.reps, 'score', v_me.score),
        'above', v_above
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'boards', v_boards,
    'lift_count', (select count(*) from public.lifts where user_id = v_uid and deleted_at is null),
    'friend_count', (select count(*) from public.friendships f
                     where f.status = 'accepted' and v_uid in (f.requester_id, f.addressee_id)),
    'group_count', (select count(*) from public.group_members where user_id = v_uid),
    'unread', public.unread_notification_count()
  );
end;
$$;

-- ───────────── Account deletion ─────────────
-- Called by the signed-in user right before the server deletes their auth user.
-- Hands off group ownership, removes them from every board, then lets FK
-- cascades remove personal data. record_history rows keep user_id = null.
create function public.prepare_account_deletion()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_group uuid;
  v_heir uuid;
begin
  if v_uid is null then raise exception 'not_authenticated'; end if;

  for v_group in select group_id from public.group_members where user_id = v_uid and role = 'owner' loop
    select user_id into v_heir from public.group_members
    where group_id = v_group and user_id <> v_uid
    order by case role when 'admin' then 0 else 1 end, joined_at
    limit 1;
    if v_heir is null then
      delete from public.groups where id = v_group;
    else
      update public.group_members set role = 'member' where group_id = v_group and user_id = v_uid;
      update public.group_members set role = 'owner' where group_id = v_group and user_id = v_heir;
    end if;
  end loop;

  update public.lifts set deleted_at = now() where user_id = v_uid and deleted_at is null;
  for v_group in select group_id from public.group_members where user_id = v_uid loop
    delete from public.group_members where group_id = v_group and user_id = v_uid;
    perform public._sync_group_all(v_group);
  end loop;
end;
$$;

